import 'server-only';

// Visuels des documents de fin de formation (certificat de réalisation et
// attestation), repris de l'outil « Attestations et certificats » C-KIM.
// Intégrés en data URI et réservés au serveur : le cachet et la signature ne
// doivent jamais être servis comme fichiers publics.

/** Logo C-KIM blanc, pour le bandeau d'en-tête foncé. */
export const LOGO_BLANC =
  'data:image/png;base64,';

/** Cachet de l'organisme et signature de son représentant légal. */
export const CACHET_SIGNATURE =
  'data:image/png;base64,';
